import{_ as l,l as i,o as e,c as n,v as r,p as s,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Percolator","description":"","frontmatter":{"title":"Percolator","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/percolator.md","filePath":"cs/percolator.md","lastUpdated":1789023840000}'),h={name:"cs/percolator.md"};function P(_,a,m,u,T,E){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="percolator" tabindex="-1">Percolator <a class="header-anchor" href="#percolator" aria-label="Permalink to &quot;Percolator&quot;">​</a></h1><div class="epigraph"><p>在无跨行事务的 Bigtable 上，用锁列、写意图与一次提交时间戳，把多行更新收成客户端驱动的 2PC 变体。</p><footer>—— 据 Peng and Dabek, Large-scale Incremental Processing Using Distributed Transactions and Notifications, OSDI 2010</footer></div><p><a href="/cs/distributed-join-shuffle">上一课</a>搬运连接数据。本课不 shuffle。缺口是宽列存储默认单行原子：索引与网页库要跨行事务。Percolator 在单元格上加 lock/write/data 列，客户端做两阶段：预写抢锁写意图，提交打时间戳。增量处理（文档更新通知）叠在事务上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bigtable 行原子、跨行无。搜索索引更新要同时改多行。缺口是<strong>把 2PC 状态机编码进表</strong>，不用独立事务管理器进程（协调器是客户端+时间戳服务器）。时间戳服务器给单调戳，类似 TSO。锁超时与崩溃：扫 lock 列清理。</p><p>与 Calvin：Percolator 悲观锁+戳，非全局定序全部事务。与 Spanner：无 TrueTime 提交等待，SI 风格。</p><p><span class="marginnote">Peng and Dabek, OSDI 2010，Google。本课机制。后续 Cockroach 等受 TSO+锁启发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Get/Prepare/Commit 协议：读带快照戳；写先对行写 lock 与新 data；全部预写成功则提交戳写入 write 列，清 lock。冲突：发现 lock 则等或 abort。通知：提交后把脏键放入队列做增量作业。</p><p>隔离：快照读 + 写写冲突检测，近似 SI，写偏斜按产品是否额外检测。</p>',10)),(e(),s(p,null,{default:t(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TS%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%20--%3E%20PW%5B%22%E9%A2%84%E5%86%99%3A%20lock%2Bdata%22%5D%0A%20%20PW%20--%3E%20CM%5B%22%E6%8F%90%E4%BA%A4%E6%88%B3%E5%86%99%E5%85%A5%20write%20%E5%88%97%22%5D%0A%20%20CM%20--%3E%20NTF%5B%22%E5%A2%9E%E9%87%8F%E9%80%9A%E7%9F%A5%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>性能：每行多列、多次 RPC，热点行锁。适合吞吐增量，不适合超短 OLTP 延迟。恢复：无独立 undo 日志，意图行即状态。WAL 在 Bigtable 层。</p><p>与 CDC：通知队列是内部 CDC。逻辑复制课的下游思想在此是同一公司流水线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 TrueTime。也不把 Percolator 当 SQL 优化器。分布式死锁后课：锁在表里，等待图跨客户端。</p><p>后课默认：可在 KV/宽列上叠客户端 2PC。Spanner 与 TrueTime：用时钟不确定区间给提交时间，实现外部一致。</p><p>把锁塞进数据表，协调器失败变成「行上残留 lock」的清理问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Percolator 用锁列与提交戳在 Bigtable 上做跨行事务。</li><li>时间戳服务器+客户端协议；适合增量，不适合超低延迟。</li><li>Spanner 与 TrueTime 下一课。</li><li>出处：Peng and Dabek, OSDI 2010。</li></ul>',9))])}const A=l(h,[["render",P]]);export{b as __pageData,A as default};
